import xml.etree.ElementTree as ET
from toysig import sign, check

def login_vulnerable(resp):
    sig = resp.find(".//Signature")
    ref = sig.find("SignedInfo/Reference").get("URI")[1:]
    signed = next(e for e in resp.iter() if e.get("ID") == ref)  # found by ID, anywhere
    if not check(sig, signed):
        return "rejected"
    return resp.find(".//Assertion/NameID").text      # but reads the FIRST assertion

def login_fixed(resp):
    found = resp.findall("Assertion")                  # absolute: Response/Assertion
    if len(found) != 1 or len(resp.findall(".//Assertion")) != 1:
        return "rejected: expected exactly one assertion"
    a = found[0]
    sig = a.find("Signature")                          # its own enveloped signature
    if sig is None or sig.find("SignedInfo/Reference").get("URI") != "#" + a.get("ID"):
        return "rejected: assertion does not sign itself"
    if not check(sig, a):
        return "rejected: bad signature"
    return a.find("NameID").text                       # use only what was verified

import hashlib

# What the SP learned from each IdP's metadata, keyed by entity ID (issuer).
# During a rollover the IdP publishes the old and the new signing certificate.
TRUST = {
    "https://idp.corp.example": {
        "sso_url": "https://idp.corp.example/sso",
        "signing_sha256": {"9f2c...old", "41ab...new"},
    },
    "https://partner-idp.example": {
        "sso_url": "https://partner-idp.example/saml",
        "signing_sha256": {"c07e...p1"},
    },
}

def fingerprint(cert_der: bytes) -> str:
    return hashlib.sha256(cert_der).hexdigest()

def key_ok(issuer: str, cert_fp: str) -> bool:
    # The key must belong to THIS issuer, never "any key we trust"
    # and never a certificate the message carries in its own KeyInfo.
    entry = TRUST.get(issuer)
    return entry is not None and cert_fp in entry["signing_sha256"]

print(key_ok("https://idp.corp.example", "41ab...new"))      # new key, right issuer
print(key_ok("https://idp.corp.example", "c07e...p1"))       # partner's key, wrong issuer
print(key_ok("https://evil.example", "41ab...new"))          # unknown issuer
print(len(fingerprint(b"example certificate bytes")), "hex characters in a SHA-256 fingerprint")

