import json

SECRET_HEADERS = {"authorization", "cookie", "set-cookie", "x-csrf-token"}

def sanitize_har(har: dict) -> dict:
    """Blank credentials before a HAR file leaves your machine."""
    for entry in har["log"]["entries"]:
        for part in (entry["request"], entry["response"]):
            for h in part.get("headers", []):
                if h["name"].lower() in SECRET_HEADERS:
                    h["value"] = "REDACTED"
            for c in part.get("cookies", []):
                c["value"] = "REDACTED"
        for q in entry["request"].get("queryString", []):
            if q["name"].lower() in {"code", "token", "access_token", "samlresponse"}:
                q["value"] = "REDACTED"
        if "postData" in entry["request"]:      # login forms, SAMLResponse posts
            entry["request"]["postData"]["text"] = "REDACTED"
    return har

har = {"log": {"entries": [{
    "request": {"url": "https://corp.okta.example/app", "headers": [
        {"name": "Cookie", "value": "sid=102Xk9...; DT=..."},
        {"name": "User-Agent", "value": "Mozilla/5.0"}],
        "cookies": [{"name": "sid", "value": "102Xk9..."}], "queryString": []},
    "response": {"headers": [{"name": "Set-Cookie", "value": "sid=102Xk9..."}],
                 "cookies": []}}]}}

clean = sanitize_har(har)
print(json.dumps(clean["log"]["entries"][0]["request"]["headers"]))
print(json.dumps(clean["log"]["entries"][0]["response"]["headers"]))

